import{z as o,x as d,o as r,c as i,q as A,j as B,D as l,d as e,s as n,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Sheared LLaMA","description":"","frontmatter":{"title":"Sheared LLaMA","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sheared-llama.md","filePath":"llm/sheared-llama.md","lastUpdated":1791413859000}'),p={name:"llm/sheared-llama.md"};function m(h,a,L,D,F,u){const t=d("Mermaid");return r(),i("div",null,[a[2]||(a[2]=A('<h1 id="sheared-llama" tabindex="-1">Sheared LLaMA <a class="header-anchor" href="#sheared-llama" aria-label="Permalink to &quot;Sheared LLaMA&quot;">​</a></h1><div class="epigraph"><p>目标不是一张掩码，而是一台更小的稠密 LLaMA：层数、隐宽、头数、FFN 中间宽一并剪到目标形状，再继续预训练把伤口养平。</p><footer>—— Xia et al., Sheared LLaMA: Accelerating Language Model Pre-training via Structured Pruning, ICLR 2024</footer></div><p><a href="/llm/two-four-sparsity">上一课</a> 依赖稀疏核才能把 50% 变成墙钟。本课走 <a href="/llm/structured-prune">结构化剪枝</a>：留下的张量仍密，任意 GEMM 都加速。缺口是 LLM 上如何把 7B 剪成指定的 1.3B / 2.7B <strong>架构</strong>，而不是按元素打孔。后课激活稀疏又把动态性接回来；本课是静态改形状。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>从零训一个 1.3B 要付满数据预算。已有 7B 检查点里有可用的层与通道。一次性幅度剪到目标形状会把知识剪断；完全从头训又浪费。Sheared LLaMA 的问题是：在目标配置（层、\\(d\\)、头、中间宽）给定时，从大模型<strong>选哪些块留下</strong>，以及剪完后如何用远少于从头训的 token 恢复。这不是 SparseGPT 的 one-shot：必须继续预训练。</p><p><span class="marginnote">术语翻译：「结构化」剪枝剪的是整块结构——整层、整个头、成片的中间通道，剪完仍是规规矩矩的小模型；「非结构化」剪枝按单个权重打孔，剪得再狠，GPU 还是按原尺寸稠密矩阵去算，不省墙钟。区别全在剪完的张量还密不密。</span></p><p>目标配置要像真的小模型，而不是「7B 去掉一半层」的畸形宽高比。否则继续预训练在错误归纳偏置上浪费。深度与宽度的取舍见主干缩放实践，本课不重开。</p><p><span class="marginnote">动态批数据（targeted / dynamic batch loading）按各域损失落后程度加采样，用来在短继续预训练里补被剪掉的领域，不是新的预训练配比理论。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两段。第一段：用梯度或激活给出的重要性，对层、头、中间通道做结构化掩码，投影到目标架构（不是任意稀疏度）。第二段：在目标形状上继续预训练，数据配比用动态加载——哪个域的损失相对目标掉得后，就多喂哪个域。报告里 7B → 1.3B / 2.7B 用的 token 明显少于同等规模从头训，下游可接近专门预训练的小模型。</p><p>不要用 Wanda 的按行配额冒充这一步。Wanda 不改 \\(d\\) 与层数，推理图仍是 7B。Sheared 改的是配置文件，推理就是小密模型。</p>',11)),(r(),B(s,null,{default:l(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Big%5B%227B%20%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%20--%3E%20IMP%5B%22%E7%BB%93%E6%9E%84%E9%87%8D%E8%A6%81%E6%80%A7%22%5D%0A%20%20TGT%5B%22%E7%9B%AE%E6%A0%87%20%E5%B1%82%2Fd%2F%E5%A4%B4%2FFFN%22%5D%20--%3E%20IMP%0A%20%20IMP%20--%3E%20Small%5B%22%E7%A8%A0%E5%AF%86%E5%B0%8F%E6%9E%B6%E6%9E%84%22%5D%0A%20%20Small%20--%3E%20CPT%5B%22%E7%BB%A7%E7%BB%AD%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%0A%20%20Lag%5B%22%E5%9F%9F%E6%8D%9F%E5%A4%B1%E8%90%BD%E5%90%8E%22%5D%20--%3E%20CPT%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("a",{href:"/llm/lora"},"LoRA"),e(" 是在原形状上加低秩增量，不减小推理 FLOPs（合并后仍是原 \\(d\\)）。本课减小的是 \\(W_0\\) 本身。二者不要写成一种「参数高效」。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("结构化删除去掉的是整块子空间。残差与层序被破坏后，下一层的激活分布移位，必须用继续预训练重新对齐。动态加载的假设是：剪枝对不同域的伤害不均，均匀配比会在已恢复的域上浪费步数。这与预训练课的 DoReMi 同类，但是"),E("strong",null,"愈合期"),e("的配比，不是从零的数据律。")],-1)),a[6]||(a[6]=E("p",null,"这张回路图回答的问题是：愈合期的数据配比怎么按「哪个域受伤最重」动态分。",-1)),(r(),B(s,null,{default:l(()=>[n(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CUT%5B%22%E7%BB%93%E6%9E%84%E5%8C%96%E5%89%AA%E6%9E%9D%EF%BC%9A%E5%88%A0%E5%B1%82%2F%E5%A4%B4%2F%E9%80%9A%E9%81%93%22%5D%20--%3E%20SHIFT%5B%22%E6%AE%8B%E5%B7%AE%E4%B8%8E%E5%B1%82%E5%BA%8F%E7%A0%B4%E5%9D%8F%EF%BC%8C%E6%BF%80%E6%B4%BB%E5%88%86%E5%B8%83%E7%A7%BB%E4%BD%8D%22%5D%0A%20%20SHIFT%20--%3E%20HEAL%5B%22%E7%BB%A7%E7%BB%AD%E9%A2%84%E8%AE%AD%E7%BB%83%EF%BC%9A%E6%84%88%E5%90%88%E6%9C%9F%22%5D%0A%20%20HEAL%20--%3E%20EVAL%7B%22%E5%93%AA%E4%B8%AA%E5%9F%9F%E7%9A%84%E6%8D%9F%E5%A4%B1%E8%90%BD%E5%90%8E%E7%9B%AE%E6%A0%87%22%7D%0A%20%20EVAL%20--%3E%7C%22%E8%90%BD%E5%90%8E%E5%A4%9A%22%7C%20MORE%5B%22%E5%A4%9A%E9%87%87%E6%A0%B7%E8%AF%A5%E5%9F%9F%22%5D%0A%20%20EVAL%20--%3E%7C%22%E5%B7%B2%E6%81%A2%E5%A4%8D%22%7C%20LESS%5B%22%E5%B0%91%E9%87%87%E6%A0%B7%E8%AF%A5%E5%9F%9F%22%5D%0A%20%20MORE%20--%3E%20HEAL%0A%20%20LESS%20--%3E%20HEAL%0A%20%20HEAL%20--%3E%20DONE%5B%22%E5%AF%B9%E9%BD%90%E5%88%B0%E7%9B%AE%E6%A0%87%E5%B0%8F%E6%9E%B6%E6%9E%84%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p>重要性若只用短校准，会偏短上下文与校准域，长上下文层或代码通道被误删——和量化校准过拟合同一病，处方是愈合数据要覆盖部署域，而不是把校准条数加到 one-shot 能救命。</p><p><span class="marginnote">常见误区：以为重要性分数是客观的。用短校准算出的「重要性」只反映校准集见过的模式——长上下文专用层、代码专用通道会在分数上垫底被误删。病根不在校准条数不够，在校准域太窄；药方是让愈合数据覆盖部署域。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有继续预训练预算时，不要走 Sheared 这条路，去 SparseGPT / 2:4。目标形状必须有现成训练配方（学习率、batch），否则愈合不稳。下一课把稀疏从权重转到激活：形状不变，前向按输入跳通道。</p><p><span class="marginnote">直觉类比：剪枝是手术，继续预训练是复健——残差与层序的破坏要靠新数据慢慢养平。没有复健预算就别动手术，选 2:4 这类「不改形状」的方案；「目标形状要有现成训练配方」则相当于复健得先有医嘱，否则愈合不稳。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Sheared LLaMA：结构化剪到目标稠密架构，再继续预训练愈合。</li><li>加速来自更小的密 GEMM，不依赖 2:4 核。</li><li>动态加载补的是被剪偏的域，不是 one-shot。</li><li>与 LoRA / Wanda 的推理图不同，检查点不互换。</li><li>出处：Xia et al., ICLR 2024。</li></ul>',7))])}const T=o(p,[["render",m]]);export{f as __pageData,T as default};
